    spracherkennung_laeuft: 'Spracherkennung läuft...',
    verarbeitung_laeuft: 'Verarbeitung läuft...',
    tipp_internetverbindung: 'Tipp: Prüfe deine Internetverbindung und versuche es erneut.',
    woerter_pro_min: 'Wörter/Min',
    avg_satzlaenge: 'Ø Satzlänge',
    woerter_einheit: 'Wörter',
    speaker_name_eingeben: 'Name für "{label}" eingeben. Wird für zukünftige Protokolle gespeichert.',
    kein_praefix: 'Kein Präfix',
    praefix_label: 'Präfix: {prefix}',
    beispiel_transkript: 'Heute haben wir die Baustelle in der Mühlenstraße 35 besichtigt. Der Rohbau ist fertiggestellt. Im Erdgeschoss fehlt noch die Elektroinstallation. Die Fenster im zweiten OG sind beschädigt und müssen ausgetauscht werden. Der Bauleiter Herr Müller war anwesend. Nächster Termin ist am Freitag um 10 Uhr.',
    vorlage_loeschen_frage: 'Vorlage "{name}" wirklich löschen?',
    hoere_zu_kapitelname: 'Höre zu... Sprich den Kapitelnamen',
    sprich_kapitelname: 'Sprich den Kapitelnamen oder tippe ihn ein',
    prompt_abnahmeprotokoll: 'Erstelle ein formelles Abnahmeprotokoll mit: 1. Objekt/Bauvorhaben, 2. Datum und Teilnehmer, 3. Gegenstand der Abnahme, 4. Festgestellte Mängel (nummeriert mit Frist), 5. Vereinbarungen, 6. Ergebnis (abgenommen/nicht abgenommen/unter Vorbehalt), 7. Unterschriftsfeld.',
    prompt_wartungsprotokoll: 'Erstelle ein Wartungsprotokoll mit: 1. Anlage/Gerät, 2. Standort, 3. Datum und Techniker, 4. Durchgeführte Arbeiten (Checkliste), 5. Festgestellte Mängel, 6. Empfohlene Maßnahmen, 7. Nächster Wartungstermin.',
    prompt_brandschutzbegehung: 'Erstelle ein Brandschutzbegehungsprotokoll mit: 1. Objekt und Datum, 2. Teilnehmer, 3. Geprüfte Bereiche, 4. Checkliste (Fluchtweg frei, Feuerlöscher vorhanden, Brandschutztüren funktionsfähig, etc.), 5. Festgestellte Mängel mit Priorität, 6. Maßnahmen und Fristen.',
    prompt_projektstatusbericht: 'Erstelle einen Projektstatusbericht mit: 1. Projekttitel und Berichtszeitraum, 2. Gesamtstatus (Ampel), 3. Erledigte Aufgaben, 4. Laufende Aufgaben, 5. Risiken und Probleme, 6. Nächste Schritte, 7. Entscheidungsbedarf.',
    prompt_kundengespraech: 'Erstelle eine strukturierte Zusammenfassung des Kundengesprächs mit: 1. Kunde und Ansprechpartner, 2. Datum und Dauer, 3. Besprochene Themen, 4. Kundenwünsche/-anforderungen, 5. Vereinbarte nächste Schritte, 6. Offene Punkte, 7. Follow-up Termin.',
    prompt_schulungsprotokoll: 'Erstelle ein Schulungsprotokoll mit: 1. Thema der Schulung, 2. Datum, Ort und Dauer, 3. Referent/Trainer, 4. Teilnehmerliste, 5. Behandelte Inhalte (Stichpunkte), 6. Praktische Übungen, 7. Offene Fragen, 8. Teilnahmebestätigung.',
    prompt_schadensgutachten: 'Erstelle ein Schadensgutachten mit: 1. Objekt und Standort, 2. Auftraggeber, 3. Datum der Besichtigung, 4. Schadensbeschreibung (detailliert), 5. Schadensursache (soweit erkennbar), 6. Schadensumfang und Bewertung, 7. Empfohlene Sanierungsmaßnahmen, 8. Geschätzte Kosten.',
    tpl_energieausweis: 'Energieausweis-Begehung',
    tpl_energieausweis_desc: 'Datenaufnahme für energetische Bewertung',
    prompt_energieausweis: 'Erstelle ein Begehungsprotokoll für die energetische Bewertung mit: 1. Gebäudedaten (Baujahr, Fläche, Geschosse), 2. Außenhülle (Wände, Dach, Fenster, Kellerdecke), 3. Heizungsanlage, 4. Warmwasserbereitung, 5. Lüftung, 6. Festgestellte energetische Schwachstellen, 7. Modernisierungsempfehlungen.',
    prompt_telefonnotiz: 'Erstelle eine Telefonnotiz mit: 1. Datum und Uhrzeit, 2. Gesprächspartner, 3. Betreff, 4. Gesprächsinhalt (Zusammenfassung), 5. Vereinbarungen/Aktionspunkte, 6. Wiedervorlage/Frist.',
    prompt_tagesrapport: 'Erstelle einen Tagesrapport mit: 1. Datum und Baustelle, 2. Wetter, 3. Arbeitskräfte (Name, Stunden, Tätigkeit), 4. Eingesetzte Geräte, 5. Verbrauchtes Material, 6. Ausgeführte Arbeiten, 7. Besondere Vorkommnisse, 8. Arbeitsstand.',
    export_vollstaendig: 'Vollständig',
