    legal_ds_3_zwecke: '3. Zwecke und vorläufige Rechtsgrundlagen',
    legal_ds_zweck_registrierung: 'Kontoregistrierung, Authentifizierung und Bereitstellung der gewünschten Appfunktionen: endgültiges B2B/B2C-Modell und konkrete Rechtsgrundlage – ',
    legal_ds_zweck_verwaltung: 'Projekt-, Protokoll-, Aufgaben- und Mängelverwaltung: Vertrag beziehungsweise dokumentiertes berechtigtes Interesse, abhängig von Verantwortungsrolle und Kundenvertrag',
    legal_ds_zweck_optionale: 'Optionale KI-, Standort-, Cloud- und Drittanbieterfunktionen: nur nach zweckbezogener Aktivierung und transparenter Information; konkrete Rechtsgrundlage ist funktionsbezogen zu dokumentieren',
    legal_ds_zweck_sicherheit: 'Sicherheit, Missbrauchsabwehr und notwendige Protokollierung: berechtigtes Interesse beziehungsweise gesetzliche Pflicht, nach dokumentierter Interessenabwägung',
    legal_ds_zweck_aufbewahrung: 'Gesetzliche Aufbewahrung und Rechtsverteidigung: nur soweit konkret erforderlich',
    legal_ds_4_lokale: '4. Lokale und serverseitige Verarbeitung',
    legal_ds_lokale_text: 'BuildKI speichert einen Teil der Projekte, Einstellungen, Medienverweise und Einwilligungsinformationen lokal auf dem Gerät. Bei Konto-, Cloud-, Synchronisations-, Upload-, E-Mail-, KI-, Zahlungs-, Dropbox-, Matterport-, Wetter- oder Pushfunktionen werden Daten zusätzlich an BuildKI-Server oder externe Anbieter übertragen. Eine Deinstallation löscht daher nicht automatisch alle Daten.',
    legal_ds_5_empfaenger: '5. Empfänger und Dienstleister',
    legal_ds_empf_backend: 'BuildKI-Backend, Datenbank und Objektspeicher – Vertragspartner, Region, AVV, Transfergrundlage und Löschfrist: ',
    legal_ds_empf_ki: 'KI-/Transkriptions-/Analyseanbieter (technischer Forge-Endpunkt) – Rechtsträger, Modelle, Region, AVV, SCC und Löschfrist: ',
    legal_ds_empf_email: 'E-Mail-Versand (technisch Strato SMTP) – Vertrag, Region, AVV und Löschfrist: ',
    legal_ds_empf_stripe: 'Stripe nur bei künftig rechtlich und Apple-konform aktiviertem Zahlungsmodell – Vertrags-/Transferangaben: ',
    legal_ds_empf_dropbox: 'Dropbox und Matterport nur bei freiwilliger Verbindung durch den Nutzer – Vertrags-/Transferangaben: ',
    legal_ds_empf_apple: 'Apple/Expo für Betriebssystem-, Push-, TestFlight- und Storeprozesse – konkrete Produktivkonfiguration: ',
    legal_ds_empf_openmeteo: 'Open-Meteo für Wetterabfragen; zu übertragen sind nur die hierfür notwendigen Standort-/Zeitparameter',
    legal_ds_6_drittland: '6. Drittlandübermittlungen',
    legal_ds_drittland_text: 'Ob und welche Anbieter Daten außerhalb EU/EWR verarbeiten, welche Angemessenheitsbeschlüsse, Standardvertragsklauseln oder zusätzlichen Maßnahmen gelten, ist je Produktivvertrag zu bestätigen.',
    legal_ds_7_speicherdauer: '7. Speicherdauer und Löschkonzept',
    legal_ds_speicher_text1: 'Verbindliche Fristen für Konten, Projekte, Audio, Video, Fotos, Transkripte, KI-Anfragen, Objektspeicher, Auditdaten, Sicherheitslogs, Zahlungsunterlagen und Backups sind noch nicht beschlossen.',
    legal_ds_speicher_text2: 'Daten werden im Prüfentwurf nicht mit einer erfundenen pauschalen 30-Tage-Frist beschrieben. Gesetzliche Aufbewahrung und technische Backupzyklen müssen je Datenkategorie dokumentiert werden.',
    legal_ds_8_audio: '8. Audio, Video, Fotos und Beschäftigtendaten',
    legal_ds_audio_text: 'Nutzer müssen vor nichtöffentlichen Audio-/Videoaufnahmen alle betroffenen Personen informieren und eine geeignete Rechtsgrundlage sicherstellen. Personenfotos, Anwesenheit, Arbeitszeit, Standort und Aufgaben können Beschäftigten- oder Drittdaten betreffen. Unternehmen müssen Erforderlichkeit, Informationspflichten, mögliche Betriebsratsmitbestimmung und erforderliche Vereinbarungen eigenständig prüfen.',
    legal_ds_9_rechte: '9. Ihre Rechte',
    legal_ds_recht_auskunft: 'Auskunft und Kopie der personenbezogenen Daten',
    legal_ds_recht_berichtigung: 'Berichtigung unrichtiger Daten',
    legal_ds_recht_loeschung: 'Löschung oder Einschränkung, soweit keine vorrangige Pflicht entgegensteht',
    legal_ds_recht_uebertragbarkeit: 'Datenübertragbarkeit, soweit anwendbar',
    legal_ds_recht_widerspruch: 'Widerspruch gegen Verarbeitungen auf Grundlage berechtigter Interessen',
    legal_ds_recht_widerruf: 'Widerruf einer Einwilligung für die Zukunft',
    legal_ds_recht_beschwerde: 'Beschwerde bei einer zuständigen Datenschutzaufsichtsbehörde',
    legal_ds_kontakt_anfragen: 'Kontakt für Anfragen: ',
    legal_ds_10_tracking: '10. Endgerätespeicherung und Tracking',
    legal_ds_tracking_text: 'Für den ausdrücklich gewünschten Appbetrieb notwendige lokale Speicherungen werden transparent dokumentiert. Ein Analytics-, Werbe-, Profiling- oder Tracking-SDK ist im geprüften Quellstand nicht nachgewiesen und wird nicht behauptet. Eine spätere Einführung erfordert eine erneute TDDDG-/DSGVO-Prüfung vor Aktivierung.',
    legal_ds_11_aktualitaet: '11. Aktualität und Veröffentlichungssperre',
    legal_ds_aktualitaet_text: 'Dieser Text ist ein technischer Prüfentwurf. Er darf erst nach Betreiberbestätigung, Dienstleister-/Transferprüfung, Löschkonzept, finaler Zahlungsentscheidung und anwaltlicher Prüfung veröffentlicht werden.',
