    legal_imp_ki_hinweis: 'KI-Hinweis',
    legal_imp_ki_text: 'KI-generierte Inhalte sind Arbeitshilfen, können fehlerhaft sein und müssen vor Freigabe, Versand oder Verwendung fachlich geprüft werden. Sie ersetzen keine rechtliche, technische oder sicherheitsrelevante Fachentscheidung.',
    legal_agb_pruefentwurf: 'Nutzungsbedingungen – Prüfentwurf',
    legal_agb_1_anbieter: '1. Anbieter, Zielgruppe und Vertragsschluss',
    legal_agb_vertragspartner: 'Vertragspartner/Anbieter',
    legal_agb_modell: 'B2B-, B2C- oder gemischtes Modell',
    legal_agb_1_text: 'Die Registrierung allein darf erst dann als Vertragsschluss bezeichnet werden, wenn Anbieter, Zielgruppe, Leistungsumfang, Tarif und Annahmeprozess verbindlich festgelegt sind.',
    legal_agb_2_leistungsumfang: '2. Leistungsumfang',
    legal_agb_2_text1: 'BuildKI unterstützt projektbezogene Baudokumentation, Protokolle, Aufgaben, Mängel, Fotos, Videos und Exporte sowie optionale Cloud-, KI- und Dropbox-Funktionen. Verfügbarkeit und Leistungsumfang richten sich nach der tatsächlich freigeschalteten Konfiguration. Nicht nachgewiesene SLAs, automatische Synchronisationsgarantien oder unbegrenzte Funktionen werden nicht zugesagt.',
    legal_agb_2_text2: 'Die Matterport-Integration ist im Prüfentwurf technisch gesperrt. Commercial Partner Terms, zulässige Monetarisierung und App-Store-Verteilung, DPA-Rollen, Transfers, Löschung, Endnutzerbedingungen sowie mandantensichere Account-/Modellzuordnung: ',
    legal_agb_3_ki: '3. KI-Funktionen',
    legal_agb_3_text: 'Transkripte, Zusammenfassungen, Berichte, Aufgaben, Übersetzungen und sonstige Vorschläge können automatisiert beziehungsweise KI-gestützt erzeugt werden. Der Nutzer muss Ergebnisse vor fachlicher oder rechtlicher Verwendung prüfen. BuildKI trifft keine autonome verbindliche Bau-, Sicherheits-, Personal- oder Rechtsentscheidung.',
    legal_agb_4_preise: '4. Preise, Testphase und Zahlung',
    legal_agb_monatspreis: 'Monatspreis',
    legal_agb_jahrespreis: 'Jahrespreis',
    legal_agb_testphase: 'Testphase',
    legal_agb_zahlungsarchitektur: 'Zahlungsarchitektur',
    legal_agb_4_text: 'Bis zur Apple- und vertragsrechtlichen Entscheidung darf kein ungeklärter externer Kauf digitaler Premiumfunktionen aus der iOS-App angeboten werden.',
    legal_agb_5_pflichten: '5. Nutzungs- und Kundenpflichten',
    legal_agb_pflicht_zugangsdaten: 'Zugangsdaten schützen und unbefugte Nutzung melden',
    legal_agb_pflicht_daten: 'Nur rechtmäßig erhobene Projekt-, Personen-, Audio-, Bild- und Beschäftigtendaten verarbeiten',
    legal_agb_pflicht_aufnahmen: 'Vor nichtöffentlichen Aufnahmen alle Betroffenen informieren und erforderliche Zustimmungen/Rechtsgrundlagen sicherstellen',
    legal_agb_pflicht_ki: 'KI-Ausgaben vor Freigabe, Versand oder Verwendung prüfen',
    legal_agb_pflicht_betriebsrat: 'Betriebsrats-, Beschäftigtendatenschutz-, Geheimhaltungs- und Kundenpflichten beachten',
    legal_agb_6_auftrag: '6. Auftragsverarbeitung und Unterauftragnehmer',
    legal_agb_6_text: 'Ob der BuildKI-Anbieter für Kundendaten als Auftragsverarbeiter handelt, welche AVV, TOM, Unterauftragnehmer, Regionen und Transfermechanismen gelten, ist vor Produktivbetrieb vertraglich festzulegen.',
    legal_agb_7_laufzeit: '7. Laufzeit, Kündigung und Daten nach Vertragsende',
