    legal_agb_loeschung: 'Löschung/gesetzliche Aufbewahrung',
    legal_agb_8_haftung: '8. Haftung, Gewährleistung und Rechtswahl',
    legal_agb_8_text: 'Gewährleistungs-, Haftungs-, Gerichtsstands-, AGB-Änderungs- und Übertragungsklauseln werden in diesem Prüfentwurf nicht als verbindlich dargestellt. Sie müssen nach Zielgruppe und Geschäftsmodell von einer qualifizierten Rechtsberatung formuliert werden.',
    legal_ki_transparenz: 'Transparenz zu KI-Funktionen',
    legal_ki_menschliche_pruefung: 'Menschliche Prüfung erforderlich',
    legal_ki_menschliche_text: 'BuildKI nutzt KI-gestützte Verarbeitung. Ergebnisse können unvollständig, missverständlich oder falsch sein und dürfen nicht ungeprüft als verbindliche Bau-, Sicherheits-, Personal- oder Rechtsentscheidung verwendet werden.',
    legal_ki_funktionen_titel: 'KI-gestützte Funktionen im geprüften Quellstand',
