    legal_ki_funktion_bautagebuch: 'Bautagebuch-, Support- und Formulierungshilfen',
    legal_ki_uebermittelte: 'Übermittelte Inhalte',
    legal_ki_uebermittelte_text: 'Je Funktion können Transkripte, Projektnamen, Protokolle, Aufgaben, Dokumente, Fotos, Anhänge und Nutzereingaben an einen serverseitig angebundenen KI-/Forge-Endpunkt übertragen werden. Eine vollständige Anonymisierung findet im geprüften Stand nicht zuverlässig statt.',
