    legal_ki_kompetenz_text: 'Betreiber und Geschäftskunden müssen Personen, die KI-Funktionen konfigurieren, bedienen oder bewerten, angemessen schulen. Ein organisatorischer Schulungs- und Freigabenachweis ist vor Veröffentlichung zu erstellen.',
