    legal_datenschutzbeauftragter: 'Data Protection Officer',
    legal_datenschutz_pruefentwurf: 'Privacy Policy – Review Draft',
    legal_ds_1_verantwortlicher: '1. Controller',
    legal_ds_dpo_notice_prefix: 'Until binding operator confirmation, ',
    legal_ds_dpo_notice_suffix: ' serves solely as a general data protection contact; a formal appointment of a data protection officer is not claimed.',
    legal_ds_2_betroffene: '2. Data Subjects and Data Categories',
    legal_ds_kat_kontoinhaber: 'Account holders: email address, name, user ID, login, verification and session data',
    legal_ds_kat_projektbeteiligte: 'Project participants and contacts: names, companies, roles, email addresses and phone numbers',
    legal_ds_kat_beschaeftigte: 'Employees and contractors: attendance, working hours, activities, tasks, responsibilities and status',
    legal_ds_kat_baustellendaten: 'Construction site data: projects, rooms, defects, protocols, appointments, locations, weather and Matterport references',
    legal_ds_kat_nutzerinhalte: 'User content: audio, video, photos, attachments, transcripts, notes, exports and AI results',
    legal_ds_kat_betriebsdaten: 'Operational data: audit, security, error, device, push and synchronization information',
    legal_ds_kat_abrechnungsdaten: 'Billing data only when a payment model is actually activated and permitted',
    legal_ds_3_zwecke: '3. Purposes and Preliminary Legal Bases',
    legal_ds_zweck_registrierung: 'Account registration, authentication and provision of the desired app functions: final B2B/B2C model and specific legal basis – ',
    legal_ds_zweck_verwaltung: 'Project, protocol, task and defect management: contract or documented legitimate interest, depending on the controller role and customer contract',
    legal_ds_zweck_optionale: 'Optional AI, location, cloud and third-party functions: only after purpose-related activation and transparent information; the specific legal basis must be documented per function',
    legal_ds_zweck_sicherheit: 'Security, abuse prevention and necessary logging: legitimate interest or legal obligation, following a documented balancing of interests',
    legal_ds_zweck_aufbewahrung: 'Legal retention and legal defense: only to the extent specifically required',
    legal_ds_4_lokale: '4. Local and Server-Side Processing',
    legal_ds_lokale_text: 'BuildKI stores part of the projects, settings, media references and consent information locally on the device. With account, cloud, synchronization, upload, email, AI, payment, Dropbox, Matterport, weather or push functions, data is additionally transmitted to BuildKI servers or external providers. Uninstalling therefore does not automatically delete all data.',
    legal_ds_5_empfaenger: '5. Recipients and Service Providers',
    legal_ds_empf_backend: 'BuildKI backend, database and object storage – contracting party, region, DPA, transfer basis and deletion period: ',
    legal_ds_empf_ki: 'AI/transcription/analysis provider (technical Forge endpoint) – legal entity, models, region, DPA, SCC and deletion period: ',
    legal_ds_empf_email: 'Email dispatch (technically Strato SMTP) – contract, region, DPA and deletion period: ',
    legal_ds_empf_stripe: 'Stripe only with a payment model activated in a future legally and Apple-compliant manner – contract/transfer details: ',
    legal_ds_empf_dropbox: 'Dropbox and Matterport only upon voluntary connection by the user – contract/transfer details: ',
    legal_ds_empf_apple: 'Apple/Expo for operating system, push, TestFlight and store processes – specific production configuration: ',
    legal_ds_empf_openmeteo: 'Open-Meteo for weather queries; only the location/time parameters necessary for this are transmitted',
    legal_ds_6_drittland: '6. Transfers to Third Countries',
    legal_ds_drittland_text: 'Whether and which providers process data outside the EU/EEA, and which adequacy decisions, standard contractual clauses or additional measures apply, must be confirmed per production contract.',
    legal_ds_7_speicherdauer: '7. Storage Period and Deletion Concept',
    legal_ds_speicher_text1: 'Binding periods for accounts, projects, audio, video, photos, transcripts, AI requests, object storage, audit data, security logs, payment records and backups have not yet been determined.',
    legal_ds_speicher_text2: 'In this review draft, data is not described with an invented blanket 30-day period. Legal retention and technical backup cycles must be documented per data category.',
    legal_ds_8_audio: '8. Audio, Video, Photos and Employee Data',
    legal_ds_audio_text: 'Before non-public audio/video recordings, users must inform all affected persons and ensure an appropriate legal basis. Photos of persons, attendance, working time, location and tasks may involve employee or third-party data. Companies must independently assess necessity, information obligations, possible works council co-determination and required agreements.',
    legal_ds_9_rechte: '9. Your Rights',
    legal_ds_recht_auskunft: 'Access to and a copy of the personal data',
    legal_ds_recht_berichtigung: 'Rectification of inaccurate data',
    legal_ds_recht_loeschung: 'Erasure or restriction, unless an overriding obligation applies',
    legal_ds_recht_uebertragbarkeit: 'Data portability, where applicable',
    legal_ds_recht_widerspruch: 'Objection to processing based on legitimate interests',
    legal_ds_recht_widerruf: 'Withdrawal of consent with future effect',
    legal_ds_recht_beschwerde: 'Complaint to a competent data protection supervisory authority',
    legal_ds_kontakt_anfragen: 'Contact for requests: ',
    legal_ds_10_tracking: '10. Device Storage and Tracking',
    legal_ds_tracking_text: 'Local storage necessary for the expressly requested app operation is documented transparently. An analytics, advertising, profiling or tracking SDK is not evidenced in the reviewed source and is not claimed. A later introduction requires a renewed TDDDG/GDPR review before activation.',
    legal_ds_11_aktualitaet: '11. Currency and Publication Embargo',
    legal_ds_aktualitaet_text: 'This text is a technical review draft. It may only be published after operator confirmation, service provider/transfer review, deletion concept, final payment decision and legal review.',
    legal_impressum_pruefentwurf: 'Imprint – Review Draft',
    legal_imp_angaben: 'Information pursuant to § 5 DDG',
    legal_imp_ladungsfaehige_anschrift: 'Address for service',
    legal_imp_vertretungsberechtigter: 'Authorized representative',
    legal_imp_telefon: 'Phone/other quick contact option',
    legal_imp_register: 'Register and Identification Numbers',
