    legal_imp_ustid: 'VAT ID or business ID no.',
    legal_imp_steuernummer_text: 'An internal tax number and bank details are not published in the imprint.',
    legal_imp_verantwortung: 'Editorial Responsibility and Support',
    legal_imp_inhaltlich_verantwortlich: 'Responsible for content',
    legal_imp_support_kontakt: 'Support and data protection contact: ',
    legal_imp_ki_hinweis: 'AI Notice',
    legal_imp_ki_text: 'AI-generated content serves as a working aid, may be erroneous and must be professionally reviewed before release, dispatch or use. It does not replace any legal, technical or safety-related expert decision.',
    legal_agb_pruefentwurf: 'Terms of Use – Review Draft',
    legal_agb_1_anbieter: '1. Provider, Target Group and Conclusion of Contract',
    legal_agb_vertragspartner: 'Contracting party/provider',
    legal_agb_modell: 'B2B, B2C or mixed model',
    legal_agb_1_text: 'Registration alone may only be described as a conclusion of contract once the provider, target group, scope of services, tariff and acceptance process have been bindingly defined.',
    legal_agb_2_leistungsumfang: '2. Scope of Services',
    legal_agb_2_text1: 'BuildKI supports project-related construction documentation, protocols, tasks, defects, photos, videos and exports as well as optional cloud, AI and Dropbox functions. Availability and scope of services depend on the actually enabled configuration. Unproven SLAs, automatic synchronization guarantees or unlimited functions are not promised.',
    legal_agb_2_text2: 'The Matterport integration is technically disabled in the review draft. Commercial Partner Terms, permissible monetization and app store distribution, DPA roles, transfers, deletion, end-user terms as well as tenant-secure account/model assignment: ',
    legal_agb_3_ki: '3. AI Functions',
    legal_agb_3_text: 'Transcripts, summaries, reports, tasks, translations and other suggestions can be generated automatically or with AI support. The user must review results before professional or legal use. BuildKI makes no autonomous binding construction, safety, personnel or legal decision.',
    legal_agb_4_preise: '4. Prices, Trial Period and Payment',
    legal_agb_monatspreis: 'Monthly price',
    legal_agb_jahrespreis: 'Annual price',
    legal_agb_testphase: 'Trial period',
    legal_agb_zahlungsarchitektur: 'Payment architecture',
    legal_agb_4_text: 'Until the Apple and contractual decision, no unresolved external purchase of digital premium functions may be offered from the iOS app.',
    legal_agb_5_pflichten: '5. Usage and Customer Obligations',
    legal_agb_pflicht_zugangsdaten: 'Protect access credentials and report unauthorized use',
    legal_agb_pflicht_daten: 'Process only lawfully collected project, personal, audio, image and employee data',
    legal_agb_pflicht_aufnahmen: 'Before non-public recordings, inform all affected persons and ensure the necessary consents/legal bases',
    legal_agb_pflicht_ki: 'Review AI outputs before release, dispatch or use',
    legal_agb_pflicht_betriebsrat: 'Observe works council, employee data protection, confidentiality and customer obligations',
    legal_agb_6_auftrag: '6. Data Processing and Subcontractors',
    legal_agb_6_text: 'Whether the BuildKI provider acts as a processor for customer data, and which DPA, TOM, subcontractors, regions and transfer mechanisms apply, must be contractually defined before production operation.',
    legal_agb_7_laufzeit: '7. Term, Termination and Data After Contract End',
    legal_agb_laufzeit_kuendigung: 'Term/termination',
    legal_agb_exportfrist: 'Export period after contract end',
    legal_agb_loeschung: 'Deletion/legal retention',
    legal_agb_8_haftung: '8. Liability, Warranty and Choice of Law',
    legal_agb_8_text: 'Warranty, liability, jurisdiction, terms-amendment and assignment clauses are not presented as binding in this review draft. They must be formulated by qualified legal counsel according to the target group and business model.',
    legal_ki_transparenz: 'Transparency on AI Functions',
    legal_ki_menschliche_pruefung: 'Human Review Required',
    legal_ki_menschliche_text: 'BuildKI uses AI-supported processing. Results may be incomplete, misleading or incorrect and must not be used unchecked as a binding construction, safety, personnel or legal decision.',
    legal_ki_funktionen_titel: 'AI-Supported Functions in the Reviewed Source',
    legal_ki_funktion_transkription: 'Audio/video transcription and speaker assignment',
    legal_ki_funktion_protokoll: 'Protocol structuring, summarization and task extraction',
