    legal_ki_funktion_bautagebuch: 'Construction diary, support and wording assistance',
    legal_ki_uebermittelte: 'Transmitted Content',
    legal_ki_uebermittelte_text: 'Depending on the function, transcripts, project names, protocols, tasks, documents, photos, attachments and user inputs can be transmitted to a server-side AI/Forge endpoint. Complete anonymization does not reliably take place in the reviewed state.',
    legal_ki_vertragspartner_label: 'Contracting party, model, region, DPA, SCC and deletion period',
    legal_ki_steuerung: 'Control and Responsibility',
    legal_ki_steuerung_freigabe: 'Optional AI processing must be actively enabled before use and be deactivatable again later',
    legal_ki_steuerung_ohne: 'Without authorization, no new content may be transmitted for AI purposes',
