    tutorial_abo_title: 'Subscription & billing',
    tutorial_start_s1: 'Create a project: Tap \'New project\' and enter name, address and description.',
    tutorial_start_s2: 'Select a project: Choose your active project in the dropdown at the top of the Tools tab.',
    tutorial_start_s3: 'All recordings and reports are assigned to the active project.',
    tutorial_aufnahme_s1: 'Switch to the Recording tab (2nd tab).',
    tutorial_aufnahme_s2: 'Press the red record button.',
    tutorial_aufnahme_s3: 'Speak freely – describe construction progress, defects, attendees.',
    tutorial_aufnahme_s4: 'Set trade markers (e.g. \'Shell\', \'Electrical\') for better structuring.',
    tutorial_aufnahme_s5: 'Take photos during the recording – they are assigned to the report.',
    tutorial_aufnahme_s6: 'Press stop – the AI automatically creates a professional report.',
    tutorial_video_s1: 'Open Tools → Video import.',
    tutorial_video_s2: 'Choose a source: gallery, files/downloads or camera.',
    tutorial_video_s3: 'You can also select multiple videos at once (batch import).',
    tutorial_video_s4: 'Videos from WhatsApp: open the video in WhatsApp → Share → BuildKI.',
    tutorial_video_s5: 'After upload, the audio track is transcribed automatically.',
    tutorial_video_s6: 'Choose the document type: meeting minutes, summary or construction diary.',
    tutorial_foto_s1: 'Open Tools → Photo analysis.',
    tutorial_foto_s2: 'Photograph an area or select a photo from the gallery.',
    tutorial_foto_s3: 'The AI analyzes the image and automatically detects defects.',
    tutorial_foto_s4: 'Adopt detected defects or add your own.',
    tutorial_foto_s5: 'Export the result as a PDF with all defects.',
    tutorial_maengel_s1: 'Open Tools → Defect list.',
    tutorial_maengel_s2: 'Create a new defect with photo, description and severity.',
    tutorial_maengel_s3: 'Assign a responsible person and set a deadline.',
    tutorial_maengel_s4: 'Track the status: Open → In progress → Re-inspection → Done.',
    tutorial_maengel_s5: 'For overdue defects you receive a push notification.',
    tutorial_maengel_s6: 'Export the defect list as a PDF for subcontractors.',
    tutorial_matterport_s1: 'Open Tools → Matterport.',
    tutorial_matterport_s2: 'Your 3D model loads automatically.',
    tutorial_matterport_s3: 'Navigate through the rooms and place pins at defect locations.',
    tutorial_matterport_s4: 'Pins are automatically linked to defect management.',
    tutorial_matterport_s5: 'The PDF export includes a link to the 3D model with a QR code.',
    tutorial_pdf_s1: 'Open a report and tap \'Export\'.',
    tutorial_pdf_s2: 'Choose the report type: report, daily site report, handover or defect list.',
    tutorial_pdf_s3: 'The PDF contains: company logo, photos, QR code and Matterport link.',
    tutorial_pdf_s4: 'Share the PDF via email, WhatsApp or save it locally.',
    tutorial_ki_s1: 'After each report, the AI automatically analyzes the content.',
    tutorial_ki_s2: 'You get hints on: missing trades, missing photos, open inspections.',
    tutorial_ki_s3: 'Open the assistant via Tools → AI assistant.',
    tutorial_ki_s4: 'The recommendations help you forget nothing and keep documentation complete.',
    tutorial_offline_s1: 'BuildKI also works without internet.',
    tutorial_offline_s2: 'Recordings and photos are stored locally.',
    tutorial_offline_s3: 'As soon as you are back online, everything syncs automatically.',
    tutorial_offline_s4: 'The sync status is shown in the settings.',
    tutorial_abo_s1: 'In the compliance review draft, no purchase or demo subscription is activated.',
    tutorial_abo_s2: 'Prices, taxes, term and target group must be defined bindingly before publication.',
    tutorial_abo_s3: 'For digital iOS features, StoreKit/In-App Purchase is the standard review path.',
    tutorial_abo_s4: 'You can find the current decision reservation under Settings → Subscription.',
